SELECT sku, name, pack, flow, price_inr, cost_inr
FROM store.products
ORDER BY sku;

SELECT COUNT(DISTINCT sku) AS skus_sold
FROM store.daily_sales
WHERE date >= '2026-06-01' AND date < '2026-07-01';

SELECT sku, audit_ts, status FROM store.shelf_audits
WHERE audit_ts >= '2026-06-01' AND audit_ts < '2026-07-01' AND status = 'empty'
ORDER BY audit_ts;
